def transform(grid):
    n = len(grid[0])
    out = [[0] * n for _ in range(n)]
    center = next((i for i, value in enumerate(grid[0]) if value == 2), n // 2)
    for r in range(n):
        for c in (center - r, center + r):
            if 0 <= c < n:
                out[r][c] = 2
        if r >= 3:
            for c in range(n):
                if c % 4 == (r + center) % 4 and abs(c - center) <= r:
                    out[r][c] = 1
    return out
